// T5 subsystem build (issue #137, docs/SELF-EXTENSION-V2.md §7) - a whole new
// crate generated by a BOUNDED supervisor + subagent split, NOT Founder OS's
// 12-path swarm (declined, AGENT-CORE.md §11). Four roles run in sequence over
// ONE shared worktree + T5 Layer B/C sandbox, each role exactly one SDK
// query() call (injectable ctx.queryFn, same DI as every other tier):
//
//   1. supervisor - read-only structured call -> a file-level plan for the
//      crate { files:[{path,purpose}], testStrategy, riskNotes }. No writes.
//   2. scaffolder - tool-using call writing the crate per the plan, in scope.
//   3. tester     - tool-using call writing/adjusting the crate's tests only.
//   4. reviewer   - read-only structured adversarial maker-checker
//      { approve, issues }. A reject triggers ONE bounded fix round
//      (scaffolder re-invoked with the issues) then a re-review; a second
//      reject FAILS the node (no endless loop).
//
// Two back-pressure budgets bound the split (docs/AGENT-CORE.md §3):
//   - a role-call cap (MAX_T5_QUERY_CALLS): supervisor+scaffolder+tester+
//     reviewer+fix+re-review = 6 calls at most.
//   - a per-node token ceiling (ctx.budget or T5_TOKEN_BUDGET), summed across
//     roles and checked BEFORE each call - a run that would exceed it stops
//     and fails with `budget_exhausted`, mirroring the agent gate's discipline.
//
// The reviewer's sign-off is threaded to the T5 validator (t5Crate.js), which
// independently re-runs cargo build/test/clippy and refuses a node without a
// recorded { approve: true }. The node then flows through the normal T3+ gate
// (awaiting_approval, requires_typed_confirm) - it is never auto-committed.
import { z } from "zod";
import { buildSandboxConfig } from "../lib/sandbox.js";
import { scopeDirs } from "../lib/tierScopes.js";
import { createWorktree, removeWorktree } from "../lib/worktree.js";
import { emitBuildEvent } from "./commit.js";
import {
  ALLOWED_TOOLS,
  READ_ONLY_TOOLS,
  DISALLOWED_TOOLS,
  BuildNodeSummary,
  buildNodeSummaryJsonSchema,
  nodeKey,
  trackedHook,
  consumeRole,
} from "./buildAgent.js";

// Named budgets - no magic numbers.
export const MAX_T5_QUERY_CALLS = 6; // supervisor+scaffolder+tester+reviewer+fix+re-review
export const T5_TOKEN_BUDGET = 4_000_000; // per-node in+out token ceiling summed across roles

// ---- role output schemas ----------------------------------------------------

export const SupervisorPlan = z.object({
  files: z.array(z.object({ path: z.string(), purpose: z.string() })).min(1),
  testStrategy: z.string(),
  riskNotes: z.string(),
});

const supervisorPlanJsonSchema = {
  type: "object",
  additionalProperties: false,
  required: ["files", "testStrategy", "riskNotes"],
  properties: {
    files: {
      type: "array",
      minItems: 1,
      items: {
        type: "object",
        additionalProperties: false,
        required: ["path", "purpose"],
        properties: { path: { type: "string" }, purpose: { type: "string" } },
      },
    },
    testStrategy: { type: "string" },
    riskNotes: { type: "string" },
  },
};

export const ReviewVerdict = z.object({
  approve: z.boolean(),
  issues: z.array(z.string()),
});

const reviewVerdictJsonSchema = {
  type: "object",
  additionalProperties: false,
  required: ["approve", "issues"],
  properties: { approve: { type: "boolean" }, issues: { type: "array", items: { type: "string" } } },
};

// ---- budget (immutable copies, never mutated) -------------------------------

function makeBudget(ceiling) {
  return { ceiling, spent: 0, calls: 0 };
}

// Fails closed with `budget_exhausted` if the next role call would breach the
// call cap or the token ceiling. Called BEFORE every role call.
function assertBudget(budget) {
  if (budget.calls >= MAX_T5_QUERY_CALLS) {
    throw new Error(`budget_exhausted: T5 role-call budget (${MAX_T5_QUERY_CALLS}) exceeded`);
  }
  if (budget.spent >= budget.ceiling) {
    throw new Error(`budget_exhausted: T5 token budget (${budget.ceiling}) exhausted after ${budget.spent} tokens`);
  }
}

function chargeBudget(budget, tokens) {
  return { ceiling: budget.ceiling, spent: budget.spent + tokens, calls: budget.calls + 1 };
}

// ---- SDK options per role ----------------------------------------------------

// Read-only role (supervisor, reviewer): inspection tools + structured output,
// no write tools, no Bash - nothing to sandbox or hook.
function readOptions(ctx, worktreePath, schema) {
  return {
    cwd: worktreePath,
    allowedTools: READ_ONLY_TOOLS,
    permissionMode: "dontAsk",
    outputFormat: { type: "json_schema", schema },
    ...(ctx.model ? { model: ctx.model } : {}),
  };
}

// Tool-writing role (scaffolder, tester): full tool set + the tier's tracked
// Layer B hook + Layer C sandbox, exactly as a T1-T4 build node.
function writeOptions(ctx, node, worktreePath) {
  const scope = { tier: node.tier, params: node.params, root: worktreePath };
  const { hook, state } = trackedHook(scope);
  const options = {
    cwd: worktreePath,
    allowedTools: ALLOWED_TOOLS,
    disallowedTools: DISALLOWED_TOOLS,
    permissionMode: "dontAsk",
    hooks: { PreToolUse: [{ matcher: "Write|Edit", hooks: [hook] }] },
    outputFormat: { type: "json_schema", schema: buildNodeSummaryJsonSchema },
    ...(ctx.model ? { model: ctx.model } : {}),
    ...buildSandboxConfig(scopeDirs(node.tier, node.params)),
  };
  return { options, state };
}

// ---- role prompts ------------------------------------------------------------

function scopeLine(node) {
  return `Write only within this tier's scope: ${scopeDirs(node.tier, node.params).join(", ")}. Never touch anything else.`;
}

function supervisorPrompt(node) {
  const { crate } = node.params;
  return [
    "You are the supervisor role for a Life OS Tier 5 subsystem build - a whole new Rust crate.",
    `Task: ${node.description}`,
    `Produce a file-level plan for crate '${crate}'. Study the sibling crates under services/ (their Cargo.toml, ` +
      "src layout, and test conventions) so the plan matches this workspace's style.",
    "Do NOT write any files - you are planning only. Your structured output must be: `files` (each an object " +
      "{ path, purpose } naming every file the scaffolder will create, all under services/" +
      `${crate}/, plus the single additive member line in services/Cargo.toml), \`testStrategy\` (how the tester ` +
      "will prove the crate builds and its behavior holds against a scratch DB), and `riskNotes` (what could go wrong).",
  ].join("\n\n");
}

function scaffolderPrompt(node, plan, issues) {
  const { crate } = node.params;
  const files = plan.files.map((f) => `- ${f.path}: ${f.purpose}`).join("\n");
  const base = [
    "You are the scaffolder role for a Life OS Tier 5 subsystem build.",
    `Task: ${node.description}`,
    scopeLine(node),
    `Write the crate '${crate}' following the supervisor's file-level plan:\n${files}`,
    `Register the crate ADDITIVELY in services/Cargo.toml: add its name to the workspace \`members\` array only - ` +
      "never remove, reorder, or edit any existing member (the t5Crate validator diff-checks this and rejects any " +
      "destructive change). Follow the sibling crates' style; write real, compiling Rust.",
  ];
  if (Array.isArray(issues) && issues.length > 0) {
    base.push(
      "The reviewer REJECTED your previous attempt for these reasons - fix every one of them:\n" +
        issues.map((i) => `- ${i}`).join("\n"),
    );
  }
  base.push("When done, your structured output must summarize: the tier, the files you changed, and a one-line summary.");
  return base.join("\n\n");
}

function testerPrompt(node, plan) {
  const { crate } = node.params;
  return [
    "You are the tester role for a Life OS Tier 5 subsystem build.",
    `Task: ${node.description}`,
    scopeLine(node),
    `Write or adjust the TESTS ONLY for crate '${crate}' - never touch its non-test source. Follow the ` +
      `supervisor's test strategy: ${plan.testStrategy}`,
    "Any test that needs a database MUST build a scratch DB via std::env::temp_dir() (the crate's own Config-literal " +
      "pattern) - NEVER the canonical lifeos.db, a `~/` path, or a hardcoded /Users/... path.",
    "When done, your structured output must summarize: the tier, the files you changed, and a one-line summary.",
  ].join("\n\n");
}

function reviewerPrompt(node, plan) {
  const { crate } = node.params;
  return [
    "You are the reviewer role for a Life OS Tier 5 subsystem build - an adversarial maker-checker.",
    `Task the crate was meant to solve: ${node.description}`,
    `Read the generated crate '${crate}' in full (its src and tests). Judge it against the supervisor's plan ` +
      `(risk notes: ${plan.riskNotes}) and this repo's conventions: does it compile-plausibly, is it in scope, ` +
      "does it perform no outward/irreversible effect directly, and do its tests use a scratch DB (never lifeos.db)?",
    "Do NOT write anything - you are reviewing only. Your structured output must be `approve` (boolean) and `issues` " +
      "(a list of concrete, actionable problems - empty when you approve). Be strict: approve only a crate you would " +
      "ship.",
  ].join("\n\n");
}

// ---- role runners ------------------------------------------------------------

function runSupervisor(ctx, node, worktreePath) {
  const options = readOptions(ctx, worktreePath, supervisorPlanJsonSchema);
  return consumeRole(ctx.queryFn, supervisorPrompt(node), options, { schema: SupervisorPlan });
}

function runScaffolder(ctx, node, worktreePath, plan, issues) {
  const { options, state } = writeOptions(ctx, node, worktreePath);
  return consumeRole(ctx.queryFn, scaffolderPrompt(node, plan, issues), options, { hookState: state, schema: BuildNodeSummary });
}

function runTester(ctx, node, worktreePath, plan) {
  const { options, state } = writeOptions(ctx, node, worktreePath);
  return consumeRole(ctx.queryFn, testerPrompt(node, plan), options, { hookState: state, schema: BuildNodeSummary });
}

function runReviewer(ctx, node, worktreePath, plan) {
  const options = readOptions(ctx, worktreePath, reviewVerdictJsonSchema);
  return consumeRole(ctx.queryFn, reviewerPrompt(node, plan), options, { schema: ReviewVerdict });
}

// ---- orchestration -----------------------------------------------------------

// Runs the bounded supervisor -> scaffolder -> tester -> reviewer sequence over
// a single worktree, with one optional fix round. Returns { summary, plan,
// review } for the downstream validate/gate stages. Throws on a budget breach
// or a second reviewer rejection - the caller discards the worktree and fails
// the node honestly.
async function runRoles(ctx, node, worktreePath) {
  const ceiling = Number.isFinite(Number(ctx.budget)) ? Number(ctx.budget) : T5_TOKEN_BUDGET;
  let budget = makeBudget(ceiling);

  assertBudget(budget);
  const supervisor = await runSupervisor(ctx, node, worktreePath);
  budget = chargeBudget(budget, supervisor.tokens);
  const plan = supervisor.data;
  await emitBuildEvent(ctx, "build.t5.planned", { tier: "T5", node: node.id, outcome: "planned", plan });

  assertBudget(budget);
  const scaffold = await runScaffolder(ctx, node, worktreePath, plan, null);
  budget = chargeBudget(budget, scaffold.tokens);

  assertBudget(budget);
  const tester = await runTester(ctx, node, worktreePath, plan);
  budget = chargeBudget(budget, tester.tokens);

  assertBudget(budget);
  let review = await runReviewer(ctx, node, worktreePath, plan);
  budget = chargeBudget(budget, review.tokens);

  if (!review.data.approve) {
    assertBudget(budget);
    const fix = await runScaffolder(ctx, node, worktreePath, plan, review.data.issues);
    budget = chargeBudget(budget, fix.tokens);

    assertBudget(budget);
    review = await runReviewer(ctx, node, worktreePath, plan);
    budget = chargeBudget(budget, review.tokens);

    if (!review.data.approve) {
      throw new Error(`T5 reviewer rejected the crate after one fix round: ${review.data.issues.join("; ")}`);
    }
  }

  const summary = {
    tier: "T5",
    files: plan.files.map((f) => f.path),
    summary: scaffold.data.summary,
  };
  return { summary, plan, review: review.data };
}

// buildT5Node(ctx, node): a fresh worktree + the bounded role split. Leaves the
// worktree in place (uncommitted) for validate.js/gate.js; the orchestrator
// removes it on every terminal path. Returns the same { alreadyCommitted:false,
// worktreePath, branch, summary } shape as buildTierNode, plus `plan`/`review`
// so the validator can require the reviewer's sign-off.
export async function buildT5Node(ctx, node) {
  const { worktreePath, branch } = await createWorktree(ctx.repoRoot, nodeKey(ctx, node));
  try {
    const result = await runRoles(ctx, node, worktreePath);
    return { alreadyCommitted: false, worktreePath, branch, ...result };
  } catch (error) {
    await removeWorktree(ctx.repoRoot, worktreePath, branch).catch(() => {});
    throw error;
  }
}
